events_list.input:
{
 "command": "find /workspace -maxdepth 4 -iname \"*health*\" 2>/dev/null",
 "description": "Find health-check related files"
}

{
 "file_path": "/workspace/scripts/health_check.sh"
}

{
 "command": "ls -la /workspace && find /workspace -iname \"*test*\" -maxdepth 3 2>/dev/null",
 "description": "List workspace root and existing tests"
}

{
 "file_path": "/workspace/README.md"
}

{
 "command": "ls -la /workspace/config /workspace/scripts /workspace/.claude/skills/shell-unit-testing",
 "description": "List config, scripts, and skill directories"
}

{
 "skill": "shell-unit-testing",
 "args": "Add reliable automated tests for /workspace/scripts/health_check.sh. Keep tests self-contained, avoid real network requests, do not modify the production script."
}

{
 "command": "mkdir -p /workspace/tests && ls /workspace",
 "description": "Create tests directory"
}

{
 "command": "chmod +x /workspace/tests/test_health_check.sh && /workspace/tests/test_health_check.sh; echo \"exit: $?\"",
 "description": "Run the health check test suite"
}

{
 "command": "type curl; declare -f curl 2>&1 | head -20; echo \"PATH=$PATH\"",
 "description": "Check if curl is a shell function or alias"
}

{
 "command": "mount | grep -E ' / | /workspace ' ; touch /workspace/tests/.exectest && chmod +x /workspace/tests/.exectest && echo '#!/bin/sh' > /workspace/tests/.exectest && echo 'echo ok' >> /workspace/tests/.exectest && /workspace/tests/.exectest; rm /workspace/tests/.exectest",
 "description": "Check exec permission on /workspace filesystem"
}

{
 "replace_all": false,
 "file_path": "/workspace/tests/test_health_check.sh",
 "old_string": "tmp_bin=\"$(mktemp -d)\"\ntrap 'rm -rf \"$tmp_bin\"' EXIT",
 "new_string": "tmp_bin=\"$(mktemp -d \"$script_dir/.mockbin.XXXXXX\")\"\ntrap 'rm -rf \"$tmp_bin\"' EXIT"
}

{
 "command": "/workspace/tests/test_health_check.sh; echo \"exit: $?\"; ls -la /workspace/tests",
 "description": "Run the health check test suite again"
}

{
 "command": "md5sum scripts/health_check.sh && cat scripts/health_check.sh",
 "description": "Confirm production script content unchanged"
}

{
 "file_path": "/workspace/config/local-service.env"
}

{
 "command": "set -a; source /workspace/config/local-service.env; set +a; echo \"URL: $HEALTH_CHECK_URL\"; /workspace/scripts/health_check.sh \"$HEALTH_CHECK_URL\"; echo \"exit: $?\"",
 "description": "Run health_check.sh against the configured local service URL"
}

{
 "command": "curl -sS --max-time 5 -o /dev/null -w \"http_code=%{http_code} exit=%?\\n\" \"http://127.0.0.1:8081/health\" 2>&1; echo \"---\"; (echo > /dev/tcp/127.0.0.1/8081) 2>&1 && echo \"port open\" || echo \"port closed/unreachable\"",
 "description": "Check whether anything is listening on the configured port"
}
